mapper.select:
select organization
from sd_user
where user_id = #{userId}


select jsonb_build_object(
    'type', 'FeatureCollection',
    'features', coalesce(jsonb_agg(
        jsonb_build_object(
            'type', 'Feature',
            'geometry', ST_AsGeoJSON(ST_Buffer(r.geom_4326::geography, #{radius})::geometry, 5)::jsonb,
            'properties', jsonb_build_object(
                'rank', r.rank,
                'featureId', r.feature_id,
                'name', coalesce(r.feature_name, concat('Feature ', r.feature_id)),
                'nearbyCount', r.nearby_count,
                'radius', #{radius}
            )
        )
    ), '[]'::jsonb)
)::text
from (
    select *
    from ranked
    order by rank
    limit #{limit}
) r
